import{_ as r,o as n,c as l,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const t="/bilder/reportverwaltung/einstellungen-globale-einstellungen-schnellzugriff.png",a="/bilder/reportverwaltung/reports-schnellzugriff-ordner.png",c=JSON.parse('{"title":"Reports über den Schnellzugriff aufrufen","description":"","frontmatter":{"title":"Reports über den Schnellzugriff aufrufen","source_pageid":1574,"source_revision":7082},"headers":[],"relativePath":"reporting/reportverwaltung/reports-ueber-den-schnellzugriff-aufrufen.md","filePath":"reporting/reportverwaltung/reports-ueber-den-schnellzugriff-aufrufen.md"}'),s={name:"reporting/reportverwaltung/reports-ueber-den-schnellzugriff-aufrufen.md"};function u(f,e,o,g,d,p){return n(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="reports-uber-den-schnellzugriff-aufrufen" tabindex="-1">Reports über den Schnellzugriff aufrufen <a class="header-anchor" href="#reports-uber-den-schnellzugriff-aufrufen" aria-label="Permalink to &quot;Reports über den Schnellzugriff aufrufen&quot;">​</a></h1><p>Mit dem Schnellzugriff öffnen Sie häufig benötigte Reports über ein schwebendes Fenster. Die Freischaltung gilt grundsätzlich für alle Nutzerinnen und Nutzer; die konkrete Reportauswahl erfolgt individuell.</p><h2 id="_1-den-schnellzugriff-aktivieren" tabindex="-1">1. Den Schnellzugriff aktivieren <a class="header-anchor" href="#_1-den-schnellzugriff-aktivieren" aria-label="Permalink to &quot;1. Den Schnellzugriff aktivieren&quot;">​</a></h2><p><a href="/bilder/reportverwaltung/einstellungen-globale-einstellungen-schnellzugriff.png"><img src="'+t+'" alt="Aktivieren Sie den Schnellzugriff, um Reports in einem schwebenden Fenster angezeigt zu bekommen." loading="lazy"></a></p><p><em>Aktivieren Sie den Schnellzugriff, um Reports in einem schwebenden Fenster angezeigt zu bekommen.</em></p><ol><li>Öffnen Sie die Einstellungen zum Reporting.</li><li>Aktivieren Sie <strong>Schnellzugriff auf Reports</strong>.</li><li>Starten Sie SchILD-NRW 3 neu. Danach steht der Schnellzugriff zur Verfügung.</li></ol><h2 id="_2-die-reports-bereitstellen" tabindex="-1">2. Die Reports bereitstellen <a class="header-anchor" href="#_2-die-reports-bereitstellen" aria-label="Permalink to &quot;2. Die Reports bereitstellen&quot;">​</a></h2><p><a href="/bilder/reportverwaltung/reports-schnellzugriff-ordner.png"><img src="'+a+'" alt="Stellen Sie Reports im Ordner Schnellzugriff bereit." loading="lazy"></a></p><p><em>Stellen Sie Reports im Ordner Schnellzugriff bereit.</em></p><p>Kopieren Sie die gewünschten Reportdateien in den Ordner <code>Standard/Schnellzugriff</code>. Nur dort bereitgestellte Reports können für den Schnellzugriff ausgewählt werden.</p><h2 id="_3-die-personliche-auswahl-festlegen" tabindex="-1">3. Die persönliche Auswahl festlegen <a class="header-anchor" href="#_3-die-personliche-auswahl-festlegen" aria-label="Permalink to &quot;3. Die persönliche Auswahl festlegen&quot;">​</a></h2><p>Öffnen Sie <strong>Verwaltung → Individuelle Einstellungen → Reporteinstellungen</strong> und wählen Sie die gewünschten Reports aus.</p><p>Die weiteren Einstellungen erläutert <a href="/administration/benutzer-einstellungen/individuelle-einstellungen-verwaltung-einstellungen.html">Individuelle Einstellungen</a>.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Reports_%C3%BCber_den_Schnellzugriff_aufrufen" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 7082.</p>',15)])])}const b=r(s,[["render",u]]);export{c as __pageData,b as default};
